    KEY_FOLD_BLOCK(aLargeC, 3U, 115U, aLargeA, 1U, 382U, aMediumD, 0U);
    KEY_FOLD_BLOCK(aLargeB, 1U, 43U, aLargeC, 0U, 182U, aMediumD, 1U);
    KEY_FOLD_BLOCK(aLargeD, 4U, 238U, aLargeB, 6U, 281U, aMediumD, 2U);
    KEY_FOLD_BLOCK(aLargeD, 6U, 474U, aLargeA, 3U, 331U, aMediumD, 3U);


    //
    // small_a (2 output blocks)
    //
    // medium_a blocks: [0]
    // medium_b blocks: [2]
    // medium_c blocks: [3]
    // medium_d blocks: [3]
    //
    KEY_FOLD_BLOCK(aMediumC, 3U, 78U, aMediumB, 2U, 81U, aSmallA, 0U);
    KEY_FOLD_BLOCK(aMediumA, 0U, 7U, aMediumD, 3U, 20U, aSmallA, 1U);


    //
    // small_b (2 output blocks)
    //
    // medium_a blocks: [3]
    // medium_b blocks: [0]
    // medium_c blocks: [0]
    // medium_d blocks: [0]
    //
    KEY_FOLD_BLOCK(aMediumA, 3U, 27U, aMediumB, 0U, 447U, aSmallB, 0U);
    KEY_FOLD_BLOCK(aMediumC, 0U, 291U, aMediumD, 0U, 374U, aSmallB, 1U);


    //
    // small_c (2 output blocks)
    //
    // medium_a blocks: [1]
    // medium_b blocks: [1]
